def calculate_monthly_salary(base_salary, hours_worked, overtime_rate=1.5):
    """Calculate monthly salary with overtime pay."""
    regular_hours = min(hours_worked, 160)
    overtime_hours = max(0, hours_worked - 160)

    hourly_rate = base_salary / 160
    regular_pay = regular_hours * hourly_rate
    overtime_pay = overtime_hours * hourly_rate * overtime_rate

    return round(regular_pay + overtime_pay, 2)

def apply_discount(price, discount_percent):
    """Apply percentage discount to original price."""
    if discount_percent < 0 or discount_percent > 100:
        raise ValueError("Discount must be between 0 and 100")
    return round(price * (1 - discount_percent / 100), 2)
